 publisher={Springer}
 abstract = {However, there is indirect evidence that other enzyme defects may be expressed in nervous tissue, including debranching enzyme deficiency (glycogenosis type III), branching enzyme},
}", "parsed": {"doi": null, "year": 1985, "gs_id": null, "pm_id": null, "title": "Disorders of glycogen metabolism", "authors": ["DiMauro, Salvatore", "De Vivo, Darryl C"], "journal": "Pathological Neurochemistry", "abstract": "However, there is indirect evidence that other enzyme defects may be expressed in nervous tissue, including debranching enzyme deficiency (glycogenosis type III), branching enzyme", "keywords": []}, "source": "Google Scholar", "metadata": {}, "paper_url": "https://link.springer.com/chapter/10.1007/978-1-4757-0797-7_1", "full_abstract": "The concentration of glycogen in the central nervous system (CNS) is approximately 0.1 g/100 g fresh tissue as compared to 1.0 g/100 g in muscle and 6–10 g/100 g in liver. Because of this low content and its rapid disappearance after death, the very presence of glycogen in the brain remained controversial until the late 1930s, when Kerr documented the presence of a polysaccharide indistinguishable from liver glycogen. 1 Major fluctuations of tissue glycogen content are accompanied by even greater changes of water content (and volume). 2 The advantages afforded the brain by the protection of the bony skull and the fibrous dura mater are attenuated by the metabolic vulnerability of the brain. The low brain tissue glycogen content renders this organ vulnerable to insult within several minutes of onset of hypoglycemia or hypoxia.", "abstract_snippet": "However, there is indirect evidence that other enzyme defects may be expressed in nervous tissue, including debranching enzyme deficiency (glycogenosis type III), branching enzyme", "has_full_abstract": true, "main_abstract_source": "publisher_page", "gs_use_publisher_full_abstract": false}}

{"google_scholar": {"bibtex": "@incollection{miranda1985hereditary,
 title={Hereditary metabolic myopathies},
 author={Miranda, Armand F and Mongini, Tiziana and DiMauro, Salvatore},
