o", "content": "Am. J. Hum. Genet."}, {"type": "abbrev_11", "content": "AM J HU GEN"}, {"type": "abbrev_29", "content": "AMER J HUM GENET"}, {"type": "item", "content": "DEFINITIVE PRENATAL-DIAGNOSIS FOR TYPE-III GLYCOGEN-STORAGE-DISEASE"}]}, "doctypes": {"count": 1, "doctype": "Article"}, "pub_info": {"vol": 47, "page": {"end": 739, "begin": 735, "content": "735-739", "page_count": 5}, "issue": 4, "pubtype": "Journal", "pubyear": 1990, "pubmonth": "OCT", "sortdate": "1990-10-01", "coverdate": "OCT 1990", "has_abstract": "Y", "journal_oas_gold": "N"}, "publishers": {"publisher": {"names": {"name": {"role": "publisher", "seq_no": 1, "addr_no": 1, "full_name": "CELL PRESS", "display_name": "CELL PRESS", "unified_name": "Elsevier"}, "count": 1}, "address_spec": {"city": "CAMBRIDGE", "addr_no": 1, "full_address": "50 HAMPSHIRE ST, FLOOR 5, CAMBRIDGE, MA 02139 USA"}}}}, "fullrecord_metadata": {"refs": {"count": 13}, "fund_ack": {"grants": {"count": 2, "grant": [{"grant_ids": {"count": 1, "grant_id": "M01-RR30"}, "grant_agency": "NCRR NIH HHS", "grant_source": "Medline", "grant_agency_names": [{"pref": "Y", "content": "United States Department of Health & Human Services"}, {"pref": "Y", "content": "National Institutes of Health (NIH) - USA"}, {"pref": "Y", "content": "NIH National Center for Research Resources (NCRR)"}, {"pref": "N", "content": "NCRR NIH HHS"}]}, {"grant_ids": {"count": 1, "grant_id": "DK39078"}, "grant_agency": "NIDDK NIH HHS", "grant_source": "Medline", "grant_agency_names": [{"pref": "Y", "content": "United States Department of Health & Human Services"}, {"pref": "Y", "content": "National Institutes of Health (NIH) - USA"}, {"pref": "Y", "content": "NIH National Institute of Diabetes & Digestive & Kidney Diseases (NIDDK)"}, {"pref": "N", "content": "NIDDK NIH HHS"}]}]}}, "abstracts": {"count": 1, "abstract": {"abstract_text": {"p": "Prenatal diagnosis for type III glycogen storage disease was performed by using (1) immunoblot analysis with a polyclonal antibody prepared against purified porcine-muscle debranching enzyme and (2) a qualitative assay for debranching-enzyme activity. Cultured amniotic fluid cells from three pregnancies (three families in which the proband that absence of debrancher protein) were subjected to immunoblot analysis. Two unaffected and one affected fetus were predicted. In addition, cultured amniotic fluid cells from nine pregnancies (eight families) were screened with a qualitative assay based on the persistence of a polysaccharide that has a structure approaching that of a phosphorylase limit dextrin when the cells were exposed to a glucose-free medium. This qualitative assay predicted six unaffected and three affected fetuses. All predictions by either method were confirmed postnatally except for one spontaneously aborted fetus. Our data indicate that a definite diagnosis of type III glycogen storage disease can be made prenatally by these methods.", "count": 1}}}, "addresses": {"count": 2, "address_name": [{"address_spec": {"zip": {"content": 27710, "location": "AP"}, "city": "DURHAM", "state": "NC", "addr_no": 1, "country": "USA", "orig_seq": 1, "full_address": "DUKE UNIV, MED CTR, DEPT PEDIAT, POB 3028, DURHAM, NC 27710 USA", "organizations": {"count": 5, "organization": [{"pref": null, "content": "DUKE UNIV"}, {"pref": "Y", "level": 0, "ror_id": "https://ror.org/00py81415", "content": "Duke University", "hierarchy_type": "incites#ringgold"}, {"pref": "N", "level": 1, "content": "Duke Medicine", "parent_pguid": "urn:org:495727", "hierarchy_type": "ringgold"}, {"pref": "N", "level": 2, "content": "Duke University School of Medicine", "parent_pguid": "urn:org:926458", "hierarchy_type": "ringgold"}, {"pref": "N", "level": 3, "content": "Duke University Department of Pediatrics", "parent_pguid": "urn:org:582259", "hierarchy_type": "ringgold"}]}, "suborganizations": {"count": 1, "suborganization": "MED CTR, DEPT PEDIAT, POB 3028"}}}, {"address_spec": {"zip": {"content": 63110, "location"